// wlasny PropertyUtils zachowujacy kolejnosc deklaracji pol:
class DeclaredOrderPropertyUtils extends PropertyUtils {
    protected Set<Property> createPropertySet(Class<?> type, BeanAccess a) {
        Set<Property> props = new LinkedHashSet<>();
        for (Field f : type.getDeclaredFields()) props.add(new FieldProperty(f));
        return props;
    }
}
